const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Jaén is approximately 37.77° N, 3.79° W.
  const jaenPoint = ee.Geometry.Point([-3.7903, 37.7692]);
  const startDate = '2023-01-01';
  const endDate = '2023-05-16'; // Exclusive end date

  // 2. Data Acquisition & Check
  const chirpsCollection = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate(startDate, endDate)
    .filterBounds(jaenPoint);

  const collectionSize = chirpsCollection.size().getInfo();
  if (collectionSize === 0) {
    console.log('Evidence: No CHIRPS images found for the specified date range and location.');
    console.log('A: No');
    return;
  }
  console.log(`Evidence: Found ${collectionSize} daily precipitation images.`);

  // 3. Processing
  // Sum all daily precipitation images to get a total for the period.
  const totalPrecipitation = chirpsCollection.sum();

  // 4. Calculation
  // Get the total precipitation value at the point. The native scale is ~5km.
  const precipitationStats = totalPrecipitation.reduceRegion({
    reducer: ee.Reducer.first(), // Use 'first' as it's a single pixel value after sum
    geometry: jaenPoint,
    scale: 5000,
    maxPixels: 1e9
  });

  const precipitationMm = precipitationStats.get('precipitation').getInfo();

  // 5. Validation & Final Answer
  if (precipitationMm === null || precipitationMm === undefined) {
    console.log('Evidence: Could not calculate precipitation at the specified point.');
    console.log('C3: Calculation Failure');
    return;
  }

  // Convert millimeters to inches (1 inch = 25.4 mm)
  const precipitationInches = precipitationMm / 25.4;
  const thresholdInches = 3;

  console.log(`Evidence: Total precipitation from ${startDate} to ${endDate.substring(0,10)} was ${precipitationMm.toFixed(2)} mm.`);
  console.log(`Evidence: This is equivalent to ${precipitationInches.toFixed(2)} inches.`);
  console.log(`Evidence: The threshold for the question is ${thresholdInches} inches.`);

  if (precipitationInches > thresholdInches) {
    console.log('A: Yes');
  } else {
    console.log('B: No');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
  console.error(e);
  console.log('D: If image, collection, or band names are incorrect, syntax or method error, wrong method, or memory issue, etc.');
});
